function message(text,error=false){$('#status').textContent=text;$('#status').className=error?'error':'success'}
async function request(url,options={}){const r=await fetch(url,{credentials:'same-origin',...options});let body;try{body=await r.json()}catch{throw Error('The server is unavailable. Please try again.')}if(!r.ok)throw Error(body.error||'Request failed');return body}
function updateSaveUI(){const save=$('#save-all'),state=$('#save-state');if(save)save.disabled=!dirty;if(state)state.textContent=dirty?'Unpublished changes':'All changes published'}
function setDirty(){dirty=true;updateSaveUI()}
async function imageSource(file){if('createImageBitmap'in window){try{return await createImageBitmap(file,{imageOrientation:'from-image'})}catch{}}return new Promise((resolve,reject)=>{const image=new Image(),url=URL.createObjectURL(file);image.onload=()=>{URL.revokeObjectURL(url);resolve(image)};image.onerror=()=>{URL.revokeObjectURL(url);reject(Error('This photo could not be opened.'))};image.src=url})}
async function galleryPhoto(file){const source=await imageSource(file),max=1800,scale=Math.min(1,max/Math.max(source.width,source.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(source.width*scale));canvas.height=Math.max(1,Math.round(source.height*scale));canvas.getContext('2d').drawImage(source,0,0,canvas.width,canvas.height);source.close?.();return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('This photo could not be prepared.')),'image/jpeg',.86))}
async function cropHeadshot(file){const dialog=$('#cropper'),canvas=$('#crop-canvas'),ctx=canvas.getContext('2d'),zoomInput=$('#crop-zoom'),source=await imageSource(file);let zoom=1,cx=source.width/2,cy=source.height/2,drag=null;const clamp=()=>{const scale=Math.max(canvas.width/source.width,canvas.height/source.height)*zoom,halfW=canvas.width/(2*scale),halfH=canvas.height/(2*scale);cx=Math.min(source.width-halfW,Math.max(halfW,cx));cy=Math.min(source.height-halfH,Math.max(halfH,cy))};const paint=()=>{clamp();const scale=Math.max(canvas.width/source.width,canvas.height/source.height)*zoom;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(source,canvas.width/2-cx*scale,canvas.height/2-cy*scale,source.width*scale,source.height*scale)};const point=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}};zoomInput.value='1';zoomInput.oninput=()=>{zoom=Number(zoomInput.value);paint()};canvas.onpointerdown=e=>{drag=point(e);canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;const p=point(e),scale=Math.max(canvas.width/source.width,canvas.height/source.height)*zoom;cx-=(p.x-drag.x)/scale;cy-=(p.y-drag.y)/scale;drag=p;paint()};canvas.onpointerup=canvas.onpointercancel=()=>{drag=null};$('#crop-reset').onclick=()=>{zoom=1;cx=source.width/2;cy=source.height/2;zoomInput.value='1';paint()};paint();dialog.showModal();return new Promise(resolve=>{const finish=value=>{dialog.close();source.close?.();resolve(value)};$('#crop-cancel').onclick=()=>finish(null);dialog.oncancel=e=>{e.preventDefault();finish(null)};$('#crop-use').onclick=()=>canvas.toBlob(blob=>finish(blob),'image/jpeg',.9)})}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
function signIn(){closeAdminMenu();$('#admin-menu-toggle').hidden=true;root.innerHTML=`<section class="login-panel"><span class="eyebrow">JERSEY DODGERS</span><h1>Admin sign-in</h1><p>Invited administrators only.</p><form id="login-form"><label>Email<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="button">Sign in</button><button type="button" id="forgot">Forgot password?</button></form></section>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await login(f.get('email'),f.get('password'));await load()}catch(err){message(err.message,true)}};$('#forgot').onclick=async()=>{const email=$('#login-form [name=email]').value;if(!email){message('Enter your email first.',true);return}try{await requestPasswordRecovery(email);message('If this account exists, a password reset link has been requested.')}catch(e){message(e.message,true)}}}
async function load(){try{const r=await request('/api/admin/content');data=r.data;revision=r.revision;dirty=false;$('#logout').hidden=false;$('#admin-menu-toggle').hidden=false;shellReady=false;draw(true);message('Signed in. Changes are published only when you choose Save & publish.')}catch(e){message(e.message,true);signIn()}}
function closeAdminMenu(){
 const nav=$('#admin-nav'),restore=nav?.contains(document.activeElement);
 document.body.classList.remove('admin-menu-open');nav?.classList.remove('open');
 if(nav)nav.inert=window.matchMedia('(max-width:700px)').matches;
 const backdrop=$('#admin-menu-backdrop');if(backdrop)backdrop.hidden=true;
 $('#admin-menu-toggle')?.setAttribute('aria-expanded','false');
 if(restore)$('#admin-menu-toggle')?.focus({preventScroll:true});
}
function openAdminMenu(){
 const nav=$('#admin-nav');if(!nav||!window.matchMedia('(max-width:700px)').matches)return;
 nav.inert=false;nav.classList.add('open');document.body.classList.add('admin-menu-open');
 $('#admin-menu-backdrop').hidden=false;$('#admin-menu-toggle').setAttribute('aria-expanded','true');
 $('#admin-menu-close')?.focus({preventScroll:true});
}
window.matchMedia('(max-width:700px)').addEventListener('change',closeAdminMenu);
document.addEventListener('keydown',e=>{
 if(!document.body.classList.contains('admin-menu-open'))return;
 if(e.key==='Escape'){e.preventDefault();closeAdminMenu();return}
 if(e.key==='Tab'){
  const items=Array.from($('#admin-nav').querySelectorAll('button,a[href]')).filter(el=>!el.disabled&&el.getClientRects().length);
  const first=items[0],last=items.at(-1);
  if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}
  else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}
 }
});
function ensureAdminShell(){
 if(shellReady&&$('#admin-shell'))return;
 const groups=adminGroups.map(item=>`<button type="button" data-admin-group="${item.id}" class="admin-group-button"><span>${esc(item.label)}</span></button>`).join('');
 root.innerHTML=`<div class="admin-layout phase1-admin" id="admin-shell"><button type="button" id="admin-menu-backdrop" aria-label="Close admin menu" tabindex="-1" hidden></button><aside class="admin-nav" id="admin-nav"><div class="admin-mobile-head"><span>CLUBHOUSE ADMIN</span><button type="button" id="admin-menu-close">Close</button></div><div class="admin-nav-title"><span>JERSEY DODGERS</span><strong>Clubhouse</strong></div><nav class="admin-group-nav" aria-label="Admin sections">${groups}</nav><div class="admin-nav-footer"><a class="admin-mobile-site" href="/" target="_blank" rel="noopener">View website</a><button type="button" class="admin-mobile-signout" id="admin-mobile-logout">Sign out</button></div></aside><section class="admin-work"><div class="admin-heading"><div><span class="eyebrow" id="admin-heading-eyebrow"></span><h1 id="admin-heading-title"></h1></div><div><span id="save-state"></span><button type="button" class="button" id="save-all">Save & publish</button></div></div><nav class="admin-subnav" id="admin-subnav"></nav><div class="admin-help" id="admin-help"></div><div id="section-content"></div></section></div>`;
 shellReady=true;
 $('#save-all').onclick=save;
 document.querySelectorAll('[data-admin-group]').forEach(b=>b.onclick=()=>{closeAdminMenu();const target=adminGroups.find(g=>g.id===b.dataset.adminGroup)?.sections[0]?.[0];if(target)navToSection(target)});
 closeAdminMenu();$('#admin-menu-close').onclick=closeAdminMenu;$('#admin-menu-backdrop').onclick=closeAdminMenu;$('#admin-mobile-logout').onclick=signOut;
}
function updateAdminChrome(){
 ensureAdminShell();
 const group=groupForSection(section);document.body.dataset.adminGroup=group.id;document.body.dataset.adminSection=section;if(section!=='graphic-generator')document.body.classList.remove('jd-graphic-active');
 document.querySelectorAll('[data-admin-group]').forEach(b=>b.classList.toggle('active',b.dataset.adminGroup===group.id));
 const tabs=$('#admin-subnav');
 if(group.sections.length>1){tabs.hidden=false;tabs.classList.remove('admin-subnav-empty');tabs.setAttribute('aria-label',`${group.label} tools`);tabs.innerHTML=group.sections.map(([key,label])=>`<button type="button" data-section="${key}" class="admin-subnav-tab ${key===section?'active':''}">${esc(label)}</button>`).join('');tabs.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{closeAdminMenu();navToSection(b.dataset.section)})}
 else{tabs.hidden=true;tabs.classList.add('admin-subnav-empty');tabs.innerHTML=''}
 $('#admin-heading-eyebrow').textContent=group.label.toUpperCase();$('#admin-heading-title').textContent=labels[section]||group.label;$('#admin-help').textContent=helpForSection(section);updateSaveUI();
}
function navToSection(next){if(!next)return;closeAdminMenu();if(next===section){updateAdminChrome();return}section=next;draw(true)}
let pluginOpenToken=0;
function openAdminPlugin(namespace,method,label){
 const targetSection=section,token=++pluginOpenToken;let tries=0;
 const attempt=()=>{
  if(token!==pluginOpenToken||section!==targetSection)return;
  const fn=window[namespace]?.[method];
  if(typeof fn==='function'){Promise.resolve(fn()).catch(error=>{if(section===targetSection){$('#section-content').innerHTML=`<div class="jd-plugin-loading is-error"><strong>${esc(label)} could not open.</strong><span>${esc(error?.message||'Please refresh and try again.')}</span></div>`;message(error?.message||`${label} could not open.`,true)}});return}
  if(++tries<40){setTimeout(attempt,50);return}
  if(section===targetSection)$('#section-content').innerHTML=`<div class="jd-plugin-loading is-error"><strong>${esc(label)} did not load.</strong><span>Refresh the Admin page and try again.</span></div>`;
 };
 attempt();
}
function draw(navigationChanged=false){
 pluginOpenToken++;
 updateAdminChrome();
 drawSection();
 if(navigationChanged)document.dispatchEvent(new CustomEvent('jd-admin-render',{detail:{section,group:groupForSection(section).id}}));
}
function dashboardGameDate(game){return `${game.rescheduledDate||game.date}T${game.rescheduledTime||game.time||'00:00'}`}
function drawDashboard(){
 const valid=data.seasons.some(s=>s.id===dashboardSeason);if(!valid)dashboardSeason=sessionStorage.getItem('jd-admin-dashboard-season')||data.settings.currentSeason||data.seasons[0]?.id||'';
 if(!data.seasons.some(s=>s.id===dashboardSeason))dashboardSeason=data.settings.currentSeason||data.seasons[0]?.id||'';
 const sid=dashboardSeason,season=data.seasons.find(s=>s.id===sid),now=new Date();
 const explicit=(data.rosters||[]).filter(r=>r.season===sid&&r.active!==false),rosterCount=explicit.length||((data.stats||[]).filter(st=>st.season===sid).length?new Set((data.stats||[]).filter(st=>st.season===sid).map(st=>st.player)).size:data.players.filter(p=>p.active).length);
 const games=data.games.filter(g=>g.season===sid).slice().sort((a,b)=>dashboardGameDate(a).localeCompare(dashboardGameDate(b)));
 const nextGame=games.find(g=>['scheduled','live','postponed'].includes(g.status)&&new Date(dashboardGameDate(g))>=new Date(now.getTime()-12*60*60*1000))||games.find(g=>['scheduled','live','postponed'].includes(g.status));
 const latest=[...games].reverse().find(g=>g.status==='final');
 const opponent=id=>data.teams.find(t=>t.id===id)?.name||'Opponent';
 const potw=(data.weeklyAwards||[]).filter(a=>a.season===sid&&a.published).length;
 const publishedMedia=data.media.filter(m=>m.published).length,featuredMedia=data.media.filter(m=>m.published&&m.featured).length;
 const statsCount=new Set([...(data.stats||[]).filter(s=>s.season===sid).map(s=>s.player),...(data.playoffStats||[]).filter(s=>s.season===sid).map(s=>s.player)]).size;
 const fmt=d=>{if(!d)return 'Not scheduled';try{return new Date(`${d}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}catch{return d}};
 $('#section-content').innerHTML=`<section class="jd-dashboard"><div class="jd-dashboard-season"><div><span class="eyebrow">DASHBOARD SEASON</span><div class="jd-dashboard-season-line"><h2>${esc(season?.name||'No season')}</h2><label>View <select id="jd-dashboard-season">${data.seasons.map(s=>`<option value="${esc(s.id)}" ${s.id===sid?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label></div><p>${esc(season?.note||'Review any season without changing the public website default.')}</p></div><button type="button" data-dashboard-section="seasons">Manage seasons</button></div><div class="jd-dashboard-metrics"><article><span>ROSTER</span><strong>${rosterCount}</strong><small>${esc(season?.name||'season')} players</small></article><article><span>STAT PROFILES</span><strong>${statsCount}</strong><small>regular + playoffs</small></article><article><span>PLAYER OF THE WEEK</span><strong>${potw}</strong><small>published this season</small></article><article><span>MEDIA LIBRARY</span><strong>${publishedMedia}</strong><small>${featuredMedia} featured · all seasons</small></article></div><div class="jd-dashboard-grid"><article class="jd-dashboard-card jd-dashboard-game"><div class="jd-card-head"><span>UP NEXT</span><button type="button" data-dashboard-section="games">Schedule</button></div>${nextGame?`<div class="jd-game-date">${esc(fmt(nextGame.rescheduledDate||nextGame.date))}</div><h3>${nextGame.home?'vs':'@'} ${esc(opponent(nextGame.opponent))}</h3><p>${esc(nextGame.rescheduledTime||nextGame.time||'Time TBA')} · ${esc(nextGame.status==='postponed'?'Postponed / reschedule pending':nextGame.status)}</p>`:'<div class="jd-dashboard-empty">No upcoming game is currently scheduled for this season.</div>'}</article><article class="jd-dashboard-card jd-dashboard-result"><div class="jd-card-head"><span>LATEST RESULT</span><button type="button" data-dashboard-section="games">Scores</button></div>${latest?`<div class="jd-game-date">${esc(fmt(latest.date))}</div><h3>Dodgers <b>${latest.ourScore??'–'}</b> <span>—</span> ${esc(opponent(latest.opponent))} <b>${latest.theirScore??'–'}</b></h3><p>${latest.ourScore>latest.theirScore?'Win':latest.ourScore<latest.theirScore?'Loss':'Tie'}${latest.recap?` · ${esc(latest.recap.slice(0,110))}`:''}</p>`:'<div class="jd-dashboard-empty">No final result has been entered for this season yet.</div>'}</article><article class="jd-dashboard-card jd-dashboard-publish"><div class="jd-card-head"><span>PUBLISH STATUS</span></div><div class="jd-publish-state ${dirty?'draft':'live'}"><i></i><div><strong>${dirty?'Unpublished changes':'Website is current'}</strong><small>${dirty?'Review your edits, then use Save & publish.':'Admin data and public website are in sync.'}</small></div></div></article></div><div class="jd-dashboard-actions"><div class="jd-card-head"><span>QUICK ACTIONS</span></div><div><button class="button" type="button" data-dashboard-section="players">+ Add / manage player</button><button type="button" data-dashboard-section="stats">Enter statistics</button><button type="button" data-dashboard-section="weeklyAwards">Players of the Week</button><button type="button" data-dashboard-section="media">Upload media</button><button type="button" data-open-graphic>Graphic Generator</button></div></div></section>`;
 $('#jd-dashboard-season')?.addEventListener('change',event=>{dashboardSeason=event.target.value;sessionStorage.setItem('jd-admin-dashboard-season',dashboardSeason);drawDashboard()});
 document.querySelectorAll('[data-dashboard-section]').forEach(b=>b.onclick=()=>navToSection(b.dataset.dashboardSection));
 document.querySelector('[data-open-graphic]')?.addEventListener('click',()=>navToSection('graphic-generator'));
}
