function title(item){if(section==='games')return item.date+' · '+(data.teams.find(x=>x.id===item.opponent)?.name||'Opponent');if(section==='stats')return (data.players.find(x=>x.id===item.player)?.name||'Player')+' · '+(data.seasons.find(x=>x.id===item.season)?.name||'Season');if(section==='standings')return data.teams.find(x=>x.id===item.team)?.name||'Team';return item.name||item.title||item.id}
function bulkMedia(){
 $('#editor-content').innerHTML=`<div class="bulk-heading"><span class="eyebrow">MEDIA GALLERY</span><h2>Upload a photo gallery</h2><p>Select several pictures at once. Sandy Cordero is preselected as the photographer, and you can turn the credit off for any gallery.</p></div><div class="bulk-form"><label>Gallery title<input id="bulk-title" placeholder="Team photo shoot" required></label><label>Date<input id="bulk-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Photographer name<input id="bulk-photographer" value="Sandy Cordero"></label><label>Photographer Instagram URL<input id="bulk-instagram" type="url" value="https://www.instagram.com/creative.lens93/"></label><label class="check-label wide"><input id="bulk-credit" type="checkbox" checked>Show photographer credit</label><label class="wide bulk-file">Choose photos<input id="bulk-files" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><label class="check-label"><input id="bulk-publish" type="checkbox" checked>Publish these photos</label><p id="bulk-message" role="status">You can select up to 30 photos at once. After upload, edit any photo to feature it in homepage position 1, 2 or 3.</p><button class="button" id="bulk-upload">Upload selected photos</button><button id="bulk-cancel">Cancel</button></div>`;
 $('#editor').showModal();$('#bulk-cancel').onclick=()=>$('#editor').close();
 $('#bulk-upload').onclick=async()=>{const files=[...$('#bulk-files').files],gallery=$('#bulk-title').value.trim(),date=$('#bulk-date').value,photographerName=$('#bulk-photographer').value.trim(),photographerInstagram=$('#bulk-instagram').value.trim(),showPhotographerCredit=$('#bulk-credit').checked;if(!gallery){$('#bulk-message').textContent='Add a gallery title first.';return}if(photographerInstagram&&!/^https:\/\//i.test(photographerInstagram)){ $('#bulk-message').textContent='Use the full https:// Instagram link.';return}if(!files.length||files.length>30){$('#bulk-message').textContent='Choose between 1 and 30 photos.';return}const button=$('#bulk-upload');button.disabled=true;const created=[];try{for(let i=0;i<files.length;i++){if(!files[i].type.startsWith('image/'))throw Error(`${files[i].name} is not an image.`);$('#bulk-message').textContent=`Preparing and uploading ${i+1} of ${files.length}: ${files[i].name}`;const photo=await galleryPhoto(files[i]),result=await request('/api/images',{method:'POST',body:photo,headers:{'Content-Type':'image/jpeg'}});created.push({id:crypto.randomUUID(),title:files.length===1?gallery:`${gallery} · ${i+1}`,caption:'',image:result.url,video:'',link:'',category:'Photos',date,photographerName,photographerInstagram,showPhotographerCredit,featured:false,featureOrder:0,published:$('#bulk-publish').checked})}const candidate=structuredClone(data);candidate.media.push(...created);data=contentSchema.parse(candidate);setDirty();$('#editor').close();draw();message(`${created.length} photos added with photographer credit. Feature your chosen three, then Save & publish.`)}catch(e){$('#bulk-message').textContent=e.message;button.disabled=false}}
}
const weeklyAwardTypes=['Player of the Week','Hitter of the Week','Pitcher of the Week','Co-Player of the Week','Custom'];
function awardWinnerDefault(index=0){return {player:data.players[0]?.id||'',awardType:index?'Co-Player of the Week':'Player of the Week',customAward:'',statLine:'',photo:'',graphic:'',stats:[]}}
function weeklyAwardDefault(){const today=new Date().toISOString().slice(0,10);return {id:crypto.randomUUID(),season:data.settings.currentSeason,weekLabel:`Week of ${new Date().toLocaleDateString(undefined,{month:'short',day:'numeric'})}`,date:today,title:'Players of the Week',summary:'',published:true,order:0,winners:[awardWinnerDefault(0)]}}
function weeklyAwardName(winner){return data.players.find(p=>p.id===winner.player)?.name||'Player'}
function weeklyAwardLabel(winner){return winner.awardType==='Custom'?(winner.customAward||'Weekly Award'):(winner.awardType||'Player of the Week')}
function weeklyAwardWinnerEditor(winner,index){const stats=[...(winner.stats||[])];while(stats.length<5)stats.push({label:'',value:''});return `<section class="jd-award-winner" data-award-winner="${index}"><div class="jd-award-winner-head"><div><span>WINNER ${index+1}</span><strong>${esc(weeklyAwardName(winner))}</strong></div><small>${index?'Optional second winner':'Primary winner'}</small></div><div class="form-grid"><label>Player<select name="winner${index}-player">${data.players.filter(p=>p.active||p.id===winner.player).map(p=>`<option value="${p.id}" ${p.id===winner.player?'selected':''}>${esc(p.name)} · #${esc(p.number)}</option>`).join('')}</select></label><label>Award<select name="winner${index}-awardType">${weeklyAwardTypes.map(v=>`<option value="${esc(v)}" ${v===winner.awardType?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="wide">Custom award name <small>Only used when Award is Custom.</small><input name="winner${index}-customAward" value="${esc(winner.customAward||'')}" placeholder="Defensive Player of the Week"></label><label class="wide">Featured stat line<input name="winner${index}-statLine" value="${esc(winner.statLine||'')}" placeholder="7-for-11 · 2 HR · 8 RBI"></label></div><div class="jd-award-assets"><label><span>Player photo override</span><small>Leave blank to use the player profile photo.</small><input type="hidden" name="winner${index}-photo" data-award-image-url="${index}-photo" value="${esc(winner.photo||'')}"><input type="file" accept="image/jpeg,image/png,image/webp" data-award-upload="${index}-photo"><span class="jd-award-preview" data-award-preview="${index}-photo">${winner.photo?`<img src="${esc(winner.photo)}" alt="Player photo override">`:'<em>Using profile photo</em>'}</span><button type="button" data-award-clear="${index}-photo">Clear override</button></label><label><span>Published graphic</span><small>Upload the finished 1080×1350 Player of the Week PNG.</small><input type="hidden" name="winner${index}-graphic" data-award-image-url="${index}-graphic" value="${esc(winner.graphic||'')}"><input type="file" accept="image/jpeg,image/png,image/webp" data-award-upload="${index}-graphic"><span class="jd-award-preview poster" data-award-preview="${index}-graphic">${winner.graphic?`<img src="${esc(winner.graphic)}" alt="Published award graphic">`:'<em>No graphic uploaded</em>'}</span><button type="button" data-award-clear="${index}-graphic">Remove graphic</button></label></div><div class="jd-award-stats"><div><strong>Featured stats</strong><small>3–5 recommended. These appear on the website card.</small></div>${stats.map((st,i)=>`<div class="jd-award-stat-row"><input name="winner${index}-stat-label-${i}" value="${esc(st.label||'')}" placeholder="AVG"><input name="winner${index}-stat-value-${i}" value="${esc(st.value||'')}" placeholder=".545"></div>`).join('')}</div></section>`}
function wireWeeklyAwardUploads(){document.querySelectorAll('[data-award-upload]').forEach(input=>input.onchange=async()=>{const file=input.files[0];if(!file)return;const key=input.dataset.awardUpload,target=document.querySelector(`[data-award-image-url="${key}"]`),preview=document.querySelector(`[data-award-preview="${key}"]`);input.disabled=true;try{message('Uploading award image…');const result=await request('/api/images',{method:'POST',body:file,headers:{'Content-Type':file.type}});target.value=result.url;preview.innerHTML=`<img src="${esc(result.url)}" alt="Uploaded award image">`;message('Image uploaded. Apply the award, then Save & publish.')}catch(e){message(e.message,true)}finally{input.disabled=false}});document.querySelectorAll('[data-award-clear]').forEach(button=>button.onclick=()=>{const key=button.dataset.awardClear,target=document.querySelector(`[data-award-image-url="${key}"]`),preview=document.querySelector(`[data-award-preview="${key}"]`);target.value='';preview.innerHTML=key.endsWith('-photo')?'<em>Using profile photo</em>':'<em>No graphic uploaded</em>'})}
function editWeeklyAward(item){const original=item,obj=item?structuredClone(item):weeklyAwardDefault();if(!obj.winners?.length)obj.winners=[awardWinnerDefault(0)];const second=obj.winners[1]||awardWinnerDefault(1);$('#editor-content').innerHTML=`<div class="jd-editor-heading"><span class="eyebrow">CONTENT / WEEKLY AWARDS</span><h2>${item?'Edit':'Create'} Players of the Week</h2><p>Publish one winner or pair a hitter and pitcher for the same week.</p></div><form id="weekly-award-form"><div class="jd-award-overview form-grid"><label>Season<select name="season">${data.seasons.map(s=>`<option value="${s.id}" ${s.id===obj.season?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Winner count<select name="winnerCount" id="award-winner-count"><option value="1" ${obj.winners.length===1?'selected':''}>1 winner</option><option value="2" ${obj.winners.length===2?'selected':''}>2 winners</option></select></label><label>Week / display label<input name="weekLabel" value="${esc(obj.weekLabel||'')}" placeholder="Week 3 · Sept 7–13" required></label><label>Date<input name="date" type="date" value="${esc(obj.date||'')}"></label><label class="wide">Section headline<input name="title" value="${esc(obj.title||'Players of the Week')}"></label><label class="wide">Weekly summary<textarea name="summary" rows="3" placeholder="Why these performances stood out this week.">${esc(obj.summary||'')}</textarea></label><label>Display order<input name="order" type="number" min="0" step="1" value="${Number(obj.order)||0}"></label><label class="check-label"><input name="published" type="checkbox" ${obj.published?'checked':''}>Published on website</label></div><div id="award-winners">${weeklyAwardWinnerEditor(obj.winners[0],0)}${weeklyAwardWinnerEditor(second,1)}</div><p class="jd-award-upload-note">Generate the poster from the Content → Graphic Generator tab first, then upload the finished PNG into each winner above.</p><p class="form-message" role="status"></p><div class="form-actions"><button class="button" type="submit">Apply weekly award</button>${original?'<button type="button" id="delete-weekly-award" class="danger">Delete award</button>':''}<button type="button" id="cancel-weekly-award">Cancel</button></div></form>`;$('#editor').showModal();const updateCount=()=>{const two=$('#award-winner-count').value==='2';document.querySelector('[data-award-winner="1"]').hidden=!two};$('#award-winner-count').onchange=updateCount;updateCount();wireWeeklyAwardUploads();$('#cancel-weekly-award').onclick=()=>$('#editor').close();$('#weekly-award-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),count=Number(f.get('winnerCount')),winners=[];for(let i=0;i<count;i++){const stats=[];for(let n=0;n<5;n++){const label=String(f.get(`winner${i}-stat-label-${n}`)||'').trim(),value=String(f.get(`winner${i}-stat-value-${n}`)||'').trim();if(label||value)stats.push({label,value})}winners.push({player:String(f.get(`winner${i}-player`)||''),awardType:String(f.get(`winner${i}-awardType`)||'Player of the Week'),customAward:String(f.get(`winner${i}-customAward`)||''),statLine:String(f.get(`winner${i}-statLine`)||''),photo:String(f.get(`winner${i}-photo`)||''),graphic:String(f.get(`winner${i}-graphic`)||''),stats})}const next={...obj,season:String(f.get('season')||''),weekLabel:String(f.get('weekLabel')||''),date:String(f.get('date')||''),title:String(f.get('title')||'Players of the Week'),summary:String(f.get('summary')||''),order:Number(f.get('order')||0),published:f.has('published'),winners};const candidate=structuredClone(data);candidate.weeklyAwards=candidate.weeklyAwards||[];if(original)candidate.weeklyAwards=candidate.weeklyAwards.map(a=>a.id===next.id?next:a);else candidate.weeklyAwards.push(next);const parsed=contentSchema.safeParse(candidate);if(!parsed.success){$('.form-message').textContent=parsed.error.issues.map(i=>i.path.join('.')+': '+i.message).join('; ');return}data=parsed.data;setDirty();$('#editor').close();draw()};if($('#delete-weekly-award'))$('#delete-weekly-award').onclick=()=>{if(!confirm('Delete this weekly award? It will disappear from the homepage after Save & publish.'))return;const candidate=structuredClone(data);candidate.weeklyAwards=(candidate.weeklyAwards||[]).filter(a=>a.id!==obj.id);data=contentSchema.parse(candidate);setDirty();$('#editor').close();draw()}}
function drawWeeklyAwards(){const awards=data.weeklyAwards||[],seasonOptions=['all',...data.seasons.map(s=>s.id)];$('#section-content').innerHTML=`<div class="jd-awards-hero"><div><span class="eyebrow">PLAYERS OF THE WEEK</span><h2>Weekly awards & homepage feature</h2><p>Choose one standout or publish a hitter + pitcher pair. Upload each finished social graphic and the same artwork can appear on the public homepage.</p></div><div><button class="button" id="add-weekly-award">+ New weekly award</button><button id="weekly-award-generator">Graphic Generator</button></div></div><div class="list-toolbar jd-awards-toolbar"><label>Season<select id="weekly-award-season">${seasonOptions.map(id=>id==='all'?'<option value="all">All seasons</option>':`<option value="${id}" ${id===data.settings.currentSeason?'selected':''}>${esc(data.seasons.find(s=>s.id===id)?.name||id)}</option>`).join('')}</select></label><label>Find<input id="weekly-award-filter" type="search" placeholder="Player, award or week"></label></div><div id="weekly-award-list"></div>`;const render=()=>{const sid=$('#weekly-award-season').value,q=$('#weekly-award-filter').value.toLowerCase(),items=awards.filter(a=>(sid==='all'||a.season===sid)&&(`${a.weekLabel} ${a.title} ${a.winners.map(w=>`${weeklyAwardName(w)} ${weeklyAwardLabel(w)}`).join(' ')}`).toLowerCase().includes(q)).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||a.order-b.order);$('#weekly-award-list').innerHTML=items.map(a=>`<article class="jd-award-admin-card"><div class="jd-award-admin-meta"><span class="${a.published?'is-live':'is-draft'}">${a.published?'PUBLISHED':'DRAFT'}</span><small>${esc(data.seasons.find(s=>s.id===a.season)?.name||'Season')} · ${esc(a.weekLabel)}</small></div><div class="jd-award-admin-winners">${a.winners.map(w=>{const p=data.players.find(x=>x.id===w.player),photo=w.graphic||w.photo||p?.photo;return `<div>${photo?`<img src="${esc(photo)}" alt="">`:`<span>#${esc(p?.number||'—')}</span>`}<p><small>${esc(weeklyAwardLabel(w))}</small><strong>${esc(p?.name||'Player')}</strong>${w.statLine?`<em>${esc(w.statLine)}</em>`:''}</p></div>`}).join('')}</div><button data-edit-weekly-award="${a.id}">Edit award</button></article>`).join('')||'<div class="jd-awards-empty"><strong>No weekly awards yet.</strong><span>Create the first one when the next Player of the Week is ready.</span></div>';document.querySelectorAll('[data-edit-weekly-award]').forEach(b=>b.onclick=()=>editWeeklyAward(awards.find(a=>a.id===b.dataset.editWeeklyAward)))};$('#weekly-award-season').onchange=render;$('#weekly-award-filter').oninput=render;$('#add-weekly-award').onclick=()=>editWeeklyAward(null);$('#weekly-award-generator').onclick=()=>navToSection('graphic-generator');render()}

function drawSection(){
 if(section==='dashboard'){drawDashboard();return}
 if(section==='players'){$('#section-content').innerHTML='<div class="jd-plugin-loading">Loading roster…</div>';openAdminPlugin('JDTeamAdmin','renderPlayers','Roster');return}
 if(section==='stats'){$('#section-content').innerHTML='<div class="jd-plugin-loading">Loading player statistics…</div>';openAdminPlugin('JDTeamAdmin','renderStats','Player statistics');return}
 if(section==='graphic-generator'){$('#section-content').innerHTML='<div class="jd-plugin-loading">Loading Graphic Generator…</div>';openAdminPlugin('JDGraphicGenerator','open','Graphic Generator');return}
 if(section==='staff-access'){$('#section-content').innerHTML='<div class="jd-plugin-loading">Loading Staff Access…</div>';openAdminPlugin('JDStaffAccess','open','Staff Access');return}
 if(section==='admin-settings'){drawAdminSettings();return}
 if(section==='weeklyAwards'){drawWeeklyAwards();return}
 if(section==='settings'){$('#section-content').innerHTML='<div class="jd-section-intro-card"><div><span class="eyebrow">PUBLIC WEBSITE</span><h2>Homepage & site content</h2><p>Branding, hero content, league links, contact details and homepage feature copy are grouped inside one organized editor.</p></div><button class="button" id="edit-settings">Edit website content</button></div><div class="settings-summary"><img src="'+esc(data.settings.heroImage)+'" alt="Current hero"><div><span class="eyebrow">CURRENT HOMEPAGE</span><h2>'+esc(data.settings.teamName)+'</h2><p>'+esc(data.settings.heroTitle)+'</p><p>'+esc(data.settings.heroText)+'</p></div></div>';$('#edit-settings').onclick=()=>edit(data.settings);return}
 let showRemoved=false;
 $('#section-content').innerHTML=`<div class="list-toolbar"><button class="button" id="add-item">+ Add ${section==='stats'?'statistics':section==='media'?'post or video':section==='standings'?'team standing':section==='players'?'player':'entry'}</button>${section==='media'?'<button id="bulk-media">Upload photo gallery</button>':''}<label>Find<input id="filter" type="search" placeholder="Search ${labels[section].toLowerCase()}"></label>${section==='stats'?'<button id="import-csv">Import season CSV</button>':section==='players'?'<button id="show-removed">Show removed players</button>':''}</div><div id="item-list"></div>`;
 const list=()=>{const q=$('#filter').value.toLowerCase(),items=data[section].filter(x=>(section!=='players'||showRemoved||x.active)&&title(x).toLowerCase().includes(q));$('#item-list').innerHTML=items.map(item=>`<div class="admin-row ${section==='players'&&!item.active?'is-removed':''}"><div class="admin-row-info">${section==='media'?`<span class="admin-media-thumb">${item.image?`<img src="${esc(item.image)}" alt="" loading="lazy">`:item.video?'<span aria-hidden="true">▶</span>':'<span aria-hidden="true">—</span>'}</span>`:''}<span><strong>${esc(title(item))}</strong><small>${esc(section==='fields'?item.address:section==='games'?item.status:section==='players'?('#'+item.number+(item.active?'':' · Removed from roster')):section==='standings'?item.w+'–'+item.l+'–'+item.t:section==='gameRecaps'?(item.date+' · '+(item.published?'Published':'Draft')):section==='media'?(item.category+' · '+(item.published?'Published':'Hidden')):'')}</small></span></div><button data-edit="${item.id}">Edit</button></div>`).join('')||'<p class="empty">No entries yet.</p>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(data[section].find(x=>x.id===b.dataset.edit)))};
 $('#filter').oninput=list;$('#add-item').onclick=()=>edit(null);if($('#bulk-media'))$('#bulk-media').onclick=bulkMedia;if($('#import-csv'))$('#import-csv').onclick=importCSV;if($('#show-removed'))$('#show-removed').onclick=()=>{showRemoved=!showRemoved;$('#show-removed').textContent=showRemoved?'Hide removed players':'Show removed players';list()};list()
}
function fieldHtml([key,label,type='text'],value){if(Array.isArray(type)||['seasons','players','teams','fields'].includes(type)){const opts=Array.isArray(type)?type.map(v=>({id:v,name:v})):data[type];return `<label>${esc(label)}<select name="${key}">${opts.map(x=>`<option value="${x.id}" ${x.id===value?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`}if(type==='checkbox')return `<label class="check-label"><input name="${key}" type="checkbox" ${value?'checked':''}>${esc(label)}</label>`;if(type==='textarea')return `<label class="wide">${esc(label)}<textarea name="${key}" rows="4">${esc(value)}</textarea></label>`;if(type==='image')return `<label class="wide">${esc(label)}<input name="${key}" value="${esc(value)}" readonly><input type="file" accept="image/jpeg,image/png,image/webp" data-upload="${key}">${value?'<img class="image-preview" src="'+esc(value)+'" alt="Current image">':''}<button type="button" data-clear-image="${key}">Remove image</button></label>`;if(type==='video')return `<label class="wide">${esc(label)}<input name="${key}" value="${esc(value)}" readonly><small>Short MP4 or WebM, up to 5 MB. Paste a YouTube link below for longer videos.</small><input type="file" accept="video/mp4,video/webm" data-video-upload="${key}">${value?'<video class="video-preview" src="'+esc(value)+'" controls></video>':''}<button type="button" data-clear-video="${key}">Remove uploaded video</button></label>`;const inputType=type==='number-null'?'number':type==='date-optional'?'date':type==='time-optional'?'time':type;return `<label>${esc(label)}<input name="${key}" type="${inputType}" ${type.startsWith('number')?'min="0" step="1"':''} value="${esc(value)}"></label>`}
const settingsEditorGroups=[
 ['Branding & Hero','Team identity, logos and the top of the homepage.',['teamName','founded','tagline','heroTitle','heroText','heroImage','logo','scriptLogo']],
 ['League & Social','League identity and official team destinations.',['leagueName','leagueLogo','leagueJoinUrl','instagram','youtube']],
 ['Contact & Season','Public contact information and the default season.',['contactEmail','applicationEmail','currentSeason']],
 ['Homepage Features','Championship, tryouts and sponsor callouts.',['championshipTitle','championshipText','championshipImage','tryoutsTitle','tryoutsText','tryoutsLink','sponsorTitle','sponsorText']],
 ['Footer & Credit','Footer copy and website credit.',['footerText','creatorName','creatorUrl']]
];
function editorFieldsHtml(sec,obj){
 if(sec!=='settings')return `<div class="form-grid">${config[sec].map(f=>fieldHtml(f,obj[f[0]])).join('')}</div>`;
 const byKey=new Map(config.settings.map(field=>[field[0],field]));
 return `<div class="jd-settings-editor">${settingsEditorGroups.map(([title,copy,keys],index)=>`<details class="jd-editor-group" ${index===0?'open':''}><summary><span><strong>${esc(title)}</strong><small>${esc(copy)}</small></span><i>+</i></summary><div class="form-grid">${keys.map(key=>byKey.get(key)).filter(Boolean).map(f=>fieldHtml(f,obj[f[0]])).join('')}</div></details>`).join('')}</div>`;
}
function installRecapEditor(){
 const form=$('#record-form'),intro=document.createElement('div');intro.className='recap-editor-intro';
 for(const name of ['lineScore','boxScore']){const input=form.querySelector(`[name="${name}"]`);input.placeholder=name==='lineScore'?'Team | 1 | 2 | 3 | R | H | E\nDodgers | 0 | 1 | 2 | 3 | 5 | 0':'Player | AB | R | H | RBI\nPlayer name | 4 | 1 | 2 | 1';input.addEventListener('paste',e=>{const html=e.clipboardData?.getData('text/html');if(!html)return;const doc=new DOMParser().parseFromString(html,'text/html'),tables=doc.querySelectorAll('table');if(tables.length!==1)return;const rows=[...tables[0].rows].map(row=>[...row.cells].map(cell=>cell.textContent.trim().replace(/\s+/g,' ')).join('\t'));if(!rows.length)return;e.preventDefault();input.setRangeText(rows.join('\n'),input.selectionStart,input.selectionEnd,'end')});}
 intro.innerHTML='<p>Paste the GameChanger link for attribution, then paste the recap and scores below. The link alone does not import sign-in-only content. For tables, copy the heading row and data rows together; tabs, pipes or two spaces separate columns. Unstructured text is preserved.</p><button type="button" id="recap-open-source">Open GameChanger link</button> <button type="button" id="recap-preview-button">Preview article</button><div id="recap-draft-preview" hidden></div>';form.prepend(intro);
 $('#recap-open-source').onclick=()=>{const url=form.querySelector('[name=source]').value.trim();try{const u=new URL(url);if(u.protocol!=='https:'||!(u.hostname==='gc.com'||u.hostname.endsWith('.gc.com')))throw Error();window.open(u.href,'_blank','noopener')}catch{$('.form-message').textContent='Paste a valid https:// GameChanger link first.'}};
 $('#recap-preview-button').onclick=()=>{const fields=Object.fromEntries(new FormData(form));fields.ourScore=fields.ourScore===''?null:Number(fields.ourScore);fields.theirScore=fields.theirScore===''?null:Number(fields.theirScore);const preview=$('#recap-draft-preview');preview.hidden=!preview.hidden;if(!preview.hidden){preview.innerHTML=recapArticle(fields);preview.scrollIntoView({block:'start'});$('#recap-preview-button').textContent='Close preview'}else $('#recap-preview-button').textContent='Preview article'};
}
function edit(item){
 const sec=section,original=item,obj=item?structuredClone(item):defaults(sec),removeLabel=sec==='players'?(obj.active?'Remove from roster':'Restore to roster'):'Remove entry';
 $('#editor-content').innerHTML=`<div class="jd-editor-heading"><span class="eyebrow">${esc(groupForSection(sec).label.toUpperCase())}</span><h2>${item?'Edit':'Add'} ${labels[sec]}</h2>${sec==='settings'?'<p>Open only the section you need. Everything else stays out of the way.</p>':''}</div><form id="record-form">${editorFieldsHtml(sec,obj)}${sec==='players'?'<small class="headshot-note">Headshots are saved in the same 4:5 portrait size for a consistent roster.</small>':''}${sec==='stats'?['bat','pitch','fielding'].map(group=>`<details open><summary>${group==='bat'?'Batting':group==='pitch'?'Pitching':'Fielding'}</summary><div class="metric-grid">${[...new Set([...(group==='bat'?['GP','PA','AB','H','AVG','OBP','OPS','SLG','HR','RBI','R','BB','SO','SB']:group==='pitch'?['IP','W','L','SV','H','R','ER','BB','SO','ERA','WHIP']:['TC','PO','A','E','FPCT','DP']),...Object.keys(obj[group]||{})])].map(k=>`<label>${esc(k)}<input name="${group}:${esc(k)}" value="${esc(obj[group]?.[k]||'')}" inputmode="decimal"></label>`).join('')}</div></details>`).join(''):''}<p class="form-message" role="status"></p><div class="form-actions"><button class="button" type="submit">Apply changes</button>${original&&sec!=='settings'?`<button type="button" id="delete-item" class="danger">${removeLabel}</button>`:''}<button type="button" id="cancel-edit">Cancel</button></div></form>`;
 if(sec==='gameRecaps')installRecapEditor();
 $('#editor').showModal();$('#cancel-edit').onclick=()=>$('#editor').close();document.querySelectorAll('[data-clear-image]').forEach(b=>b.onclick=()=>{$(`[name="${b.dataset.clearImage}"]`).value='';b.parentElement.querySelector('img')?.remove()});document.querySelectorAll('[data-clear-video]').forEach(b=>b.onclick=()=>{$(`[name="${b.dataset.clearVideo}"]`).value='';b.parentElement.querySelector('video')?.remove()});
 document.querySelectorAll('[data-upload]').forEach(el=>el.onchange=async()=>{const selected=el.files[0];if(!selected)return;const submit=$('#record-form [type=submit]');submit.disabled=true;try{let file=selected;if(sec==='players'&&el.dataset.upload==='photo'){file=await cropHeadshot(selected);if(!file){el.value='';return}}$('.form-message').textContent='Uploading photo…';const result=await request('/api/images',{method:'POST',body:file,headers:{'Content-Type':file.type}});$(`[name="${el.dataset.upload}"]`).value=result.url;let preview=el.parentElement.querySelector('img');if(!preview){preview=document.createElement('img');preview.className='image-preview';el.parentElement.append(preview)}preview.src=result.url;$('.form-message').textContent=(sec==='players'?'Headshot cropped and uploaded.':'Photo uploaded.')+' Apply changes, then Save & publish.'}catch(e){$('.form-message').textContent=e.message}finally{submit.disabled=false}});
 document.querySelectorAll('[data-video-upload]').forEach(el=>el.onchange=async()=>{const file=el.files[0];if(!file)return;const submit=$('#record-form [type=submit]');submit.disabled=true;try{if(file.size>5000000)throw Error('Choose a short video under 5 MB. Paste a YouTube link for longer videos.');$('.form-message').textContent='Uploading video…';const result=await request('/api/videos',{method:'POST',body:file,headers:{'Content-Type':file.type}});$(`[name="${el.dataset.videoUpload}"]`).value=result.url;let preview=el.parentElement.querySelector('video');if(!preview){preview=document.createElement('video');preview.className='video-preview';preview.controls=true;el.parentElement.append(preview)}preview.src=result.url;$('.form-message').textContent='Video uploaded. Apply changes, then Save & publish.'}catch(e){$('.form-message').textContent=e.message}finally{submit.disabled=false}});
 $('#record-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);for(const [key,,type='text']of config[sec])obj[key]=type==='checkbox'?f.has(key):type==='number'?Number(f.get(key)):type==='number-null'?(f.get(key)===''?null:Number(f.get(key))):String(f.get(key)||'');if(sec==='stats'){for(const group of ['bat','pitch','fielding']){obj[group]={};for(const [key,v]of f)if(key.startsWith(group+':'))obj[group][key.slice(group.length+1)]=String(v)}}const candidate=structuredClone(data);if(sec==='settings')candidate.settings=obj;else if(original)candidate[sec]=candidate[sec].map(x=>x.id===obj.id?obj:x);else candidate[sec].push(obj);const parsed=contentSchema.safeParse(candidate);if(!parsed.success){$('.form-message').textContent=parsed.error.issues.map(i=>i.path.join('.')+': '+i.message).join('; ');return}data=parsed.data;setDirty();$('#editor').close();draw()};
 if($('#delete-item'))$('#delete-item').onclick=()=>{const candidate=structuredClone(data);if(sec==='players'){const nextActive=!obj.active;if(!confirm(nextActive?'Restore this player to the public roster?':'Remove this player from the public roster? His photo and past statistics will be saved.'))return;candidate.players=candidate.players.map(x=>x.id===obj.id?{...x,active:nextActive}:x)}else{if(!confirm('Remove this entry? It will disappear after Save & publish.'))return;candidate[sec]=candidate[sec].filter(x=>x.id!==obj.id)}const parsed=contentSchema.safeParse(candidate);if(!parsed.success){$('.form-message').textContent='This entry is used by another record. Remove or update those references first.';return}data=parsed.data;setDirty();$('#editor').close();draw();message(sec==='players'?(obj.active?'Player removed from the roster. Choose Save & publish to finish.':'Player restored. Choose Save & publish to finish.'):'Entry removed. Choose Save & publish to finish.')}
}
function defaults(sec){const item={id:crypto.randomUUID()};for(const [k,,t='text']of config[sec])item[k]=t==='checkbox'?true:t==='number'?0:t==='number-null'?null:Array.isArray(t)?t[0]:['seasons','players','teams','fields'].includes(t)?data[t][0]?.id||'':'';if(sec==='gameRecaps'){item.published=false;item.date=new Date().toISOString().slice(0,10);item.author='Jersey Dodgers'}if(sec==='players'){item.active=true;item.bio=''}if(sec==='games'){item.timezone='America/New_York';item.time='10:00';item.date=new Date().toISOString().slice(0,10);item.season=data.settings.currentSeason}if(sec==='stats'){item.bat={};item.pitch={};item.fielding={};item.season=data.settings.currentSeason}if(sec==='media'){item.photographerName='Sandy Cordero';item.photographerInstagram='https://www.instagram.com/creative.lens93/';item.showPhotographerCredit=true;item.featured=false;item.featureOrder=0}if(sec==='channels')item.color='#168bff';if(sec==='sponsors')item.buttonLabel='Visit sponsor';return item}
async function save(){if(busy)return;busy=true;$('#save-all').disabled=true;message('Saving and publishing…');try{const result=await request('/api/admin/content',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,data})});revision=result.revision;data=result.data;dirty=false;updateAdminChrome();if(!['graphic-generator','staff-access','players','stats'].includes(section))drawSection();message('Published. Your website now uses these changes.')}catch(e){message(e.message,true);$('#save-all').disabled=false}finally{busy=false}}
function parseCSV(text){const rows=[];let row=[],value='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){value+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(value);value=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(Boolean))rows.push(row);row=[];value=''}else value+=c}if(value||row.length){row.push(value);rows.push(row)}return rows}
const playerKey=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
function importCSV(){$('#editor-content').innerHTML=`<h2>Refresh stats from GameChanger</h2><p>Choose the target season before selecting the weekly export. Existing totals in that season are replaced. Returning players reuse their saved profile, photo and past-season history.</p><label class="import-season-card"><strong>IMPORT THESE STATS INTO</strong><select id="import-season">${data.seasons.map(s=>`<option value="${s.id}" ${s.id===data.settings.currentSeason?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>GameChanger CSV file<input type="file" id="csv-file" accept=".csv,text/csv"></label><p id="import-message" role="status"></p><button class="button" id="read-csv">Review import</button><button id="apply-import" hidden>Apply import to draft</button>`;$('#editor').showModal();let imported;$('#read-csv').onclick=async()=>{try{const f=$('#csv-file').files[0];if(!f||f.size>4000000)throw Error('Choose a CSV under 4 MB.');const rows=parseCSV(await f.text());const hi=rows.findIndex(r=>r[0]==='Number'&&r[1]==='Last'&&r[2]==='First');if(hi<1)throw Error('Expected a GameChanger export with Number, Last, First and Batting/Pitching/Fielding sections.');const group=rows[hi-1],headers=rows[hi],pi=group.indexOf('Pitching'),fi=group.indexOf('Fielding');if(pi<0||fi<0)throw Error('Pitching and fielding sections not found.');const candidate=structuredClone(data);let count=0,added=0,reused=0;const sid=$('#import-season').value,seasonLabel=data.seasons.find(s=>s.id===sid)?.name||sid;for(const row of rows.slice(hi+1)){if(!row[0]||['Totals','Glossary'].includes(row[0])||row.length<headers.length)continue;const name=(row[2]+' '+row[1]).trim();if(!name)continue;const matches=candidate.players.filter(p=>playerKey(p.name)===playerKey(name));let p=matches.find(p=>p.number===row[0]);if(!p&&matches.length===1)p=matches[0];if(!p){p={...defaults('players'),id:crypto.randomUUID(),name,number:row[0]};candidate.players.push(p);added++}else{p.active=true;reused++}const existing=candidate.stats.find(s=>s.player===p.id&&s.season===sid);const values=(a,b)=>Object.fromEntries(headers.slice(a,b).map((k,j)=>[k,row[a+j]]));const stats={id:existing?.id||crypto.randomUUID(),season:sid,player:p.id,bat:values(3,pi),pitch:values(pi,fi),fielding:values(fi,headers.length),source:'Team-imported GameChanger CSV'};if(existing)candidate.stats=candidate.stats.map(x=>x.id===existing.id?stats:x);else candidate.stats.push(stats);count++}if(!count)throw Error('No player rows found.');imported=contentSchema.parse(candidate);$('#import-message').textContent=`${seasonLabel}: ${count} stat rows ready · ${reused} saved player profiles reused · ${added} new profiles. Nothing is published yet.`;$('#apply-import').hidden=false}catch(e){imported=null;$('#apply-import').hidden=true;$('#import-message').textContent=e.message}};$('#apply-import').onclick=()=>{if(!imported)return;data=imported;setDirty();$('#editor').close();draw();message('Import applied to your draft. Review it, then Save & publish.')}}
async function signOut(){if(dirty&&!confirm('Discard unpublished changes and sign out?'))return;await logout();dirty=false;data=null;shellReady=false;$('#logout').hidden=true;$('#admin-menu-toggle').hidden=true;signIn()}
window.JDAdminNavigate=navToSection;
window.JDAdminSection=()=>section;
$('#editor .close').onclick=()=>$('#editor').close();$('#logout').onclick=signOut;$('#admin-menu-toggle').onclick=()=>{if(document.body.classList.contains('admin-menu-open'))closeAdminMenu();else openAdminMenu()};
(async()=>{try{const callback=await handleAuthCallback();if(callback?.type==='invite'||callback?.type==='recovery'){root.innerHTML='<section class="login-panel"><h1>Set your admin password</h1><form id="password-form"><label>New password<input name="password" type="password" minlength="12" autocomplete="new-password" required></label><button class="button">Save password</button></form></section>';$('#password-form').onsubmit=async e=>{e.preventDefault();try{const pw=new FormData(e.target).get('password');if(callback.type==='invite')await acceptInvite(callback.token,pw);else await updateUser({password:pw});await load()}catch(err){message(err.message,true)}};return}if(await getUser())await load();else signIn()}catch(e){message(e.message,true);signIn()}})();
